<?php use Agent\Views as V; $count = 0; ?>
<?php foreach ($threads as $row): if ($row['visibility'] !== $tab) continue; $count++; ?>
<div class="thread-row"><a class="thread-item <?=$current && $current['thread']['id'] == $row['id'] ? 'active' : ''?>" href="<?=V::url('?thread=' . $row['id'])?>" data-thread="<?=$row['id']?>"><strong><?=V::h(trim($row['title']) !== '' ? $row['title'] : 'New conversation')?></strong><small><?=V::h($row['visibility'] === 'team' ? 'Team conversation' : 'Conversation')?></small></a><?php if ((string)$row['owner_id'] === (string)$state['user']['id']): ?><form method="post" class="delete-thread-form"><?=V::csrf($state, 'delete-thread')?><input type="hidden" name="thread_id" value="<?=$row['id']?>"><button class="icon thread-delete" aria-label="Delete conversation <?=V::h($row['title'] ?: 'New conversation')?>"><?=V::icon('trash')?></button></form><?php endif; ?></div>
<?php endforeach; if (!$count): ?><div class="empty">A little quiet here.<br>Start a conversation.</div><?php endif; ?>
